(()=>{'use strict';
const M=window.KaiserConfig,$=s=>document.querySelector(s),root=$('#konfigurator');if(!root||!M)return;
const euro=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let structure=false,activeBlock='hero';
const desktopView=()=>window.matchMedia('(min-width:851px)').matches;
let state=M.initial(),step=0,category='Inhalte',device=desktopView()?'desktop':'mobile',page='Start',filter='Alle',search='',expanded=desktopView();
const industries={
 service:{label:'Dienstleistung',headline:'Die passende Lösung beginnt mit einem Gespräch.',sub:'Wir machen komplexe Aufgaben verständlich und begleiten dich von der ersten Frage bis zur Umsetzung.',image:'assets/references/ref-01-gabelstaplerfahrschule-v8.webp',imageAlt:'Beispiel einer Dienstleister-Website mit klarer Leistungsdarstellung',cta:'Beratung anfragen',services:[['Persönliche Beratung','Wir hören zu, klären deinen Bedarf und zeigen die Möglichkeiten.'],['Individuelle Lösungen','Ein passender Vorschlag mit verständlichem Leistungsumfang.'],['Begleitung im Alltag','Ein fester Kontakt für Fragen und die nächsten Schritte.']],about:'Fachwissen trifft persönlichen Kontakt.',aboutCopy:'Stelle hier deine Spezialisierung, Arbeitsweise und Ansprechpartner vor. So wissen Interessenten, wem sie ihr Anliegen anvertrauen.',process:[['Anliegen klären','Wir besprechen deine Ausgangslage und dein Ziel.'],['Lösung planen','Du bekommst einen Vorschlag mit transparentem Umfang.'],['Gemeinsam umsetzen','Wir setzen die vereinbarten Schritte sorgfältig um.']],contact:'Welche Unterstützung brauchst du?',contactCopy:'Beschreibe kurz dein Anliegen. Wir melden uns mit den nächsten Schritten.'},
 craft:{label:'Handwerk & Bau',headline:'Dein Vorhaben. Sorgfältig umgesetzt.',sub:'Von der ersten Besichtigung bis zum letzten Handgriff: Wir planen mit dir und machen unsere Arbeit nachvollziehbar.',image:'assets/references/butz-bauwelt-hires.webp',imageAlt:'Website-Beispiel aus der Baubranche mit modernem Wohnhaus',cta:'Bauvorhaben besprechen',services:[['Neubau & Planung','Deine Vorstellungen werden zur Grundlage einer klaren Planung.'],['Sanierung & Modernisierung','Bestehendes erhalten und sinnvoll weiterentwickeln.'],['Ausführung & Service','Abgestimmte Leistungen und ein direkter Ansprechpartner.']],about:'Das Handwerk hinter deinem Projekt.',aboutCopy:'Zeige deinen Betrieb, dein Team und echte Einblicke in die Arbeit. Mit eigenen Referenzen wird deine Erfahrung konkret.',process:[['Vorhaben besprechen','Wir klären Wünsche, Standort und den vorhandenen Bestand.'],['Angebot abstimmen','Leistungen und Ablauf werden gemeinsam festgelegt.'],['Projekt umsetzen','Du erhältst Einblick in Fortschritt und nächste Schritte.']],contact:'Was möchtest du bauen oder verändern?',contactCopy:'Erzähl uns von deinem Vorhaben, dem Standort und deinem gewünschten Zeitraum.'},
 beauty:{label:'Beauty & Lifestyle',headline:'Dein Stil. Unsere Leidenschaft.',sub:'Ein Look, der zu dir passt. Mit persönlicher Beratung und Zeit für deine Wünsche.',image:'assets/references/ref-03-avanti-haarstudio-v8.webp',imageAlt:'Salon-Website als Beispiel für Beauty und Lifestyle',cta:'Termin anfragen',services:[['Schnitt & Styling','Passend zu deinem Typ und deinem Alltag.'],['Farbe & Veränderung','Gemeinsam finden wir die Richtung für deinen neuen Look.'],['Pflege & Beratung','Individuelle Empfehlungen für zuhause.']],about:'Lerne deinen Salon kennen.',aboutCopy:'Stelle dein Team vor und zeige die Atmosphäre im Salon. Persönliche Bilder vermitteln schon vor dem ersten Termin ein Gefühl für deinen Betrieb.',process:[['Wünsche erzählen','Welcher Look gefällt dir und was ist dir wichtig?'],['Persönlich beraten','Wir stimmen Schnitt, Farbe oder Behandlung mit dir ab.'],['Wohlfühlen','Genieße deinen Termin und nimm Pflegetipps mit.']],contact:'Zeit für deinen nächsten Termin?',contactCopy:'Nenne uns deine gewünschte Leistung und einen passenden Zeitraum. Wir bestätigen den Termin persönlich.'},
 hospitality:{label:'Gastronomie & Aufenthalt',headline:'Ankommen. Genießen. Gerne bleiben.',sub:'Entdecke unser Haus, unser Angebot und die kleinen Details, die deinen Besuch besonders machen.',image:'assets/references/ref-05-der-stern-v2.webp',imageAlt:'Atmosphärische Gastronomie-Website als Branchenbeispiel',cta:'Besuch anfragen',services:[['Essen & Trinken','Ein Einblick in Karte, Spezialitäten und aktuelle Angebote.'],['Unser Haus','Atmosphäre und Räume schon vor dem Besuch entdecken.'],['Besondere Anlässe','Platz für gemeinsame Abende und persönliche Feiern.']],about:'Ein erster Eindruck von deinem Lieblingsort.',aboutCopy:'Zeige deine Gastgeber, Räume und das Angebot. Ergänze später eigene Bilder, Öffnungszeiten und Informationen zur Anreise.',process:[['Angebot entdecken','Lerne unser Haus und die Möglichkeiten kennen.'],['Besuch abstimmen','Teile uns Datum, Personenzahl und Wünsche mit.'],['Ankommen & genießen','Wir freuen uns auf deinen Besuch.']],contact:'Wann dürfen wir dich begrüßen?',contactCopy:'Schreibe uns dein Wunschdatum und die Personenzahl. Deine Anfrage wird persönlich bestätigt.'},
 other:{label:'Andere Branche',headline:'Dein Angebot. Klar auf den Punkt.',sub:'Zeige, was dein Unternehmen besonders macht und wie deine Kunden davon profitieren.',image:'assets/references/aurelia-yachts.webp',imageAlt:'Kreativer Yacht-Showcase als Beispiel für eine individuelle Markenwebsite',cta:'Kontakt aufnehmen',services:[['Dein Angebot','Erkläre, welche Leistung oder welches Produkt du anbietest.'],['Dein Unterschied','Zeige, was deine Arbeitsweise besonders macht.'],['Dein Service','Mach den nächsten Schritt für Interessenten einfach.']],about:'Die Geschichte hinter deinem Unternehmen.',aboutCopy:'Hier bekommen deine Haltung, deine Arbeit und die Menschen hinter der Marke Raum. Wir stimmen den Inhalt auf deine Branche ab.',process:[['Kennenlernen','Wir besprechen deine Wünsche und Erwartungen.'],['Abstimmen','Du erfährst, wie es weitergeht und was enthalten ist.'],['Loslegen','Wir begleiten dich zum vereinbarten Ergebnis.']],contact:'Lass uns über deine Idee sprechen.',contactCopy:'Was ist dir wichtig? Erzähle uns davon und wir melden uns persönlich.'}
};
const packageInfo={
start:{for:'Für einen kompakten, professionellen Einstieg.',features:['1 Onepager mit bis zu 5 Inhaltsabschnitten','Zum Beispiel Einstieg, Leistungen, Über dich, Ablauf und Kontakt','Bewährtes Basislayout mit deinen Farben und deinem Logo','Kontaktformular und direkte Kontaktwege','1 gebündelte Korrekturrunde'],note:'Texte und Bilder lieferst du. Besondere Funktionen sind optional.'},
business:{for:'Für Unternehmen, die ihr Angebot ausführlicher zeigen möchten.',features:['Bis zu 5 Inhaltsseiten mit klarer Navigation','Zum Beispiel Start, Leistungen, Über uns, Projekte und Kontakt','Individuell abgestimmte Gestaltung für dein Unternehmen','Bis zu 5 Inhaltsabschnitte je Standardseite','2 gebündelte Korrekturrunden'],note:'Eine einfache Projektvorstellung ist möglich. Filter, Galeriefunktionen und CMS werden bei Bedarf ergänzt.'},
premium:{for:'Für Marken, die ihren Auftritt besonders inszenieren möchten.',features:['Bis zu 5 Inhaltsseiten mit individueller Inszenierung','1 cineastische Scroll-Sequenz mit geliefertem Material','Dezente Scroll-Animationen für bis zu 5 Bereiche','Bis zu 5 Inhaltsabschnitte je Standardseite','2 gebündelte Korrekturrunden'],note:'Video- und 3D-Produktion sind nicht enthalten. Weitere Sequenzen und Funktionen lassen sich ergänzen.'}
};

const goals={
 leads:{label:'Mehr Anfragen',short:'Anfragen',copy:'Klare Wege zur Kontaktaufnahme und mehr Vertrauenssignale.',recs:['reviews','form','gallery']},
 professional:{label:'Professioneller auftreten',short:'Marke',copy:'Ein hochwertiger Auftritt mit starken Referenzen und Bewegung.',recs:['gallery','reviews','motion']},
 recruiting:{label:'Mitarbeiter gewinnen',short:'Recruiting',copy:'Arbeitgeberprofil, Stellen und eine einfache Bewerbung.',recs:['career','application','video']},
 appointments:{label:'Termine generieren',short:'Termine',copy:'Direkte Buchung plus Vertrauen und eine klare Anfrage.',recs:['booking','reviews','form']},
 projects:{label:'Projekte präsentieren',short:'Projekte',copy:'Arbeiten groß zeigen, filtern und als Case Study vertiefen.',recs:['gallery','case','compare']}
};
const palettes={
 kaiser:{label:'Kaiser',primary:'#32d8f5',accent:'#ae70ff',bg:'#f7f8f9',dark:false},
 minimal:{label:'Minimal',primary:'#c4d4d8',accent:'#6f768b',bg:'#f6f7f8',dark:false},
 warm:{label:'Warm',primary:'#d9a86c',accent:'#6f4d38',bg:'#faf7f2',dark:false},
 night:{label:'Night',primary:'#b6ff43',accent:'#32d8f5',bg:'#17181d',dark:true}
};
const contentLabels={text:'Texte',images:'Bilder',logo:'Logo'};
let lastTotal=null;
function selectedExtraCount(){return Object.values(state.extras||{}).filter(Boolean).length;}
function contentState(key){return state.content?.[key]||'open';}
function goalInfo(){return goals[state.goal]||goals.leads;}
function sectionTitle(id,fallback){return state.sectionTitles?.[id]||fallback;}
function recommendationItems(){return goalInfo().recs.map(id=>M.extras.find(x=>x.id===id)).filter(Boolean);}
function pageNames(){const names=['Start','Leistungen','Über uns','Projekte','Kontakt'];while(names.length<state.pages)names.push('Seite '+(names.length+1));const out=state.pages===1?['Start']:names.slice(0,state.pages);if(state.extras.career)out.push('Karriere');for(let n=0;n<(state.extras.case||0);n++)out.push('Projekt '+(n+1));return out;}
function styleCard(id,label,sub){return `<button type="button" class="style-card" data-style="${id}" aria-pressed="${state.style===id}"><span class="style-mini style-mini-${id}" aria-hidden="true"><i></i><i></i><i></i><b>KAISER</b><em></em><small></small></span><span><b>${label}</b><small>${sub}</small></span></button>`;}
function recButtons(){return recommendationItems().map(x=>{const included=x.id==='motion'&&state.package==='premium',chosen=!!state.extras[x.id]||included;return `<button type="button" class="goal-rec ${chosen?'is-chosen':''}" data-rec-add="${x.id}" aria-pressed="${chosen}" ${included?'disabled':''}><span>${chosen?'✓':'+'}</span><b>${x.name}</b><small>${included?'Im Paket enthalten':chosen?'Ausgewählt · abwählen':'Für dein Ziel sinnvoll'}</small></button>`;}).join('');}
function packageCards(){ $('#config-packages').innerHTML=Object.entries(M.packages).map(([id,p],i)=>`<article class="package-card ${state.package===id?'is-selected':''}"><button type="button" class="package-pick" data-package="${id}" aria-pressed="${state.package===id}"><span class="package-top"><span>0${i+1} / ${p.name.toUpperCase()}</span><span class="package-check" aria-hidden="true">${state.package===id?'✓':'↗'}</span></span><strong>${p.description}</strong><span class="package-price"><small>ab</small> ${euro(p.price)}</span><span class="package-audience">${packageInfo[id].for}</span><span class="package-select-label">${state.package===id?'Dein gewähltes Paket':'Dieses Paket wählen'} ↗</span></button><details class="package-mobile-expand"><summary><span>Enthaltene Leistungen</span><span class="package-mobile-expand-icon" aria-hidden="true">+</span></summary><ul>${packageInfo[id].features.map(f=>'<li>'+f+'</li>').join('')}</ul><p>${packageInfo[id].note}</p></details><ul class="package-features">${packageInfo[id].features.map(f=>'<li>'+f+'</li>').join('')}</ul><details class="package-detail"><summary>Gut zu wissen</summary><p>${packageInfo[id].note}</p><p>Mobiloptimierung, Kontaktformular, technische SEO-Grundlagen und Einbindung gelieferter Rechtstexte sind in jedem Paket enthalten. Hosting, Domain und externe Lizenzen separat.</p></details></article>`).join('');}
function inputPanel(){const g=goalInfo();return `<div class="config-panel-title"><span>01 / DEIN AUFTRITT</span><h3>Gib deiner Idee<br>ein Gesicht.</h3><p>Du bestimmst Ziel, Stil und Inhalt. Die Vorschau reagiert direkt.</p></div>
<fieldset class="config-field config-subsection"><legend>Was soll deine Website hauptsächlich erreichen?</legend><div class="goal-choices">${Object.entries(goals).map(([id,x])=>`<button type="button" data-goal="${id}" aria-pressed="${state.goal===id}"><span>${x.label}</span><small>${x.copy}</small></button>`).join('')}</div><details class="goal-recommendations"><summary>Passende Empfehlungen ansehen</summary><span>Für „${g.label}“</span>${recButtons()}</details></fieldset>
<label class="config-field">Unternehmensname<input id="config-name" maxlength="48" value="${esc(state.name)}" autocomplete="organization"></label><label class="config-field">Deine Branche<select id="config-industry">${Object.entries(industries).map(([id,v])=>`<option value="${id}" ${state.industry===id?'selected':''}>${v.label}</option>`).join('')}</select></label>
<fieldset class="config-field config-subsection"><legend>Welche Richtung passt zu dir?</legend><div class="style-choices style-choices-premium">${styleCard('clear','Klar','Ruhig · präzise')}${styleCard('editorial','Elegant','Editorial · hochwertig')}${styleCard('bold','Markant','Direkt · selbstbewusst')}</div></fieldset>
<fieldset class="config-field config-subsection"><legend>Deine Farbwelt</legend><div class="palette-choices">${Object.entries(palettes).map(([id,x])=>`<button type="button" data-palette="${id}" aria-pressed="${state.palette===id}"><span class="palette-preview"><i style="--c:${x.primary}"></i><i style="--c:${x.accent}"></i><i style="--c:${x.bg}"></i></span><b>${x.label}</b></button>`).join('')}</div><details class="brand-customizer" ${state.palette==='custom'?'open':''}><summary>Farben fein abstimmen</summary><div class="brand-color-grid"><label>Primary<input id="config-color" type="color" value="${state.color||'#32d8f5'}"></label><label>Accent<input id="config-accent-color" type="color" value="${state.accent2||'#ae70ff'}"></label><label>Background<input id="config-bg-color" type="color" value="${state.background||'#f7f8f9'}"></label></div></details></fieldset>
<label class="config-toggle"><span>Dunkle Gestaltung</span><input type="checkbox" id="config-dark" ${state.dark?'checked':''}></label>
<div class="config-page-control"><div><b>Inhaltsseiten</b><span>${M.packages[state.package].pages} im Paket · weitere je 119 €</span></div><div class="config-counter"><button type="button" data-pages="-1" aria-label="Eine Inhaltsseite weniger" ${state.pages<=1?'disabled':''}>−</button><output>${state.pages}</output><button type="button" data-pages="1" aria-label="Eine Inhaltsseite mehr" ${state.pages>=30?'disabled':''}>+</button></div></div><p class="config-hint">Bei einer Seite liegen die Inhalte untereinander. Ab zwei Seiten wächst die Navigation. Rechtstextseiten zählen nicht mit.</p>
<fieldset class="config-field config-subsection"><legend>Wie weit bist du mit deinen Inhalten?</legend><div class="content-check">${Object.entries(contentLabels).map(([id,label])=>`<article><div><b>${label}</b><small>${contentState(id)==='ready'?'Vorhanden':'Noch offen / Unterstützung möglich'}</small></div><div><button type="button" data-content="${id}" data-content-status="ready" aria-pressed="${contentState(id)==='ready'}">Vorhanden</button><button type="button" data-content="${id}" data-content-status="open" aria-pressed="${contentState(id)==='open'}">Offen</button></div></article>`).join('')}</div>${contentState('text')==='open'?`<button type="button" class="content-help" data-rec-add="copy" ${state.extras.copy?'disabled':''}>${state.extras.copy?'✓ Texterstellung eingeplant':'＋ Unterstützung bei Texten einplanen'}</button>`:''}</fieldset>
<div class="config-included"><b>Dein ${M.packages[state.package].name}-Paket enthält</b><ul>${packageInfo[state.package].features.map(f=>'<li>'+f+'</li>').join('')}</ul><p>Außerdem: mobile Darstellung, Kontaktformular, Seitentitel und Meta-Beschreibungen sowie Einbindung gelieferter Rechtstexte.</p></div>`;}
function extrasPanel(){const count=Object.values(state.extras).filter(Boolean).length;return `<div class="config-panel-title"><span>02 / DEINE MÖGLICHKEITEN</span><h3>Was soll deine<br>Website können?</h3><p>Wähle gezielt. Deine Vorschau wächst mit.</p></div><div class="extra-categories" role="group" aria-label="Zusatzleistungen filtern">${[...new Set(M.extras.map(x=>x.category))].map(c=>`<button type="button" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><p class="extra-count">${count} Ergänzung${count===1?'':'en'} gewählt · Preise einmalig</p><div class="extras-list">${M.extras.filter(x=>x.category===category).map(x=>{const q=state.extras[x.id]||0,included=x.id==='motion'&&state.package==='premium';return `<article class="extra-item ${q?'chosen':''} ${goalInfo().recs.includes(x.id)?'recommended':''}"><label><input type="checkbox" data-extra="${x.id}" ${q||included?'checked':''} ${included?'disabled':''}><span><b>${x.name}${goalInfo().recs.includes(x.id)?'<em>EMPFOHLEN</em>':''}</b><small>${x.kind==='quote'?'Individuelles Angebot':included?'Im Premium-Paket enthalten':(x.kind==='min'?'ab ':'+')+euro(x.price)+(x.id==='language'?' + 39 € / Seite':x.type==='qty'?' je Einheit':'')}</small></span></label><p>${x.description}</p>${x.requires?'<p class="extra-dependency">Benötigt den Mitgliederbereich; wird bei Auswahl ergänzt.</p>':''}${x.type==='qty'&&q?`<div class="extra-quantity"><span>Anzahl</span><div class="config-counter"><button type="button" data-quantity="${x.id}" data-delta="-1" aria-label="${x.name}: weniger">−</button><output>${q}</output><button type="button" data-quantity="${x.id}" data-delta="1" aria-label="${x.name}: mehr" ${q>=20?'disabled':''}>+</button></div></div>`:''}</article>`;}).join('')}</div><p class="config-hint">Team, Leistungen oder einfache FAQ können bereits Teil deiner enthaltenen Abschnitte sein. Die Extras ergänzen den hier beschriebenen Funktionsumfang; eine separate Abschnittsgebühr fällt dafür nicht an.</p>`;}
function summaryPanel(){const c=M.calculate(state);return `<div class="config-panel-title"><span>03 / DEINE ZUSAMMENSTELLUNG</span><h3>Dein nächster<br>Schritt ist klar.</h3><p>Prüfe deine Auswahl. Du kannst jederzeit zurückgehen.</p></div><div class="config-summary-meta"><article><span>Ziel</span><b>${esc(goalInfo().label)}</b></article><article><span>Design</span><b>${state.style==='editorial'?'Elegant':state.style==='bold'?'Markant':'Klar'} · ${esc(palettes[state.palette]?.label||'Custom')}</b></article><article><span>Content</span><b>${Object.values(state.content||{}).filter(v=>v==='ready').length}/3 vorhanden</b></article></div><div class="config-receipt">${c.lines.map(l=>`<div><span>${esc(l.name)}${l.min?' <small>ab</small>':''}</span><b>${euro(l.amount)}</b></div>`).join('')}<div class="receipt-total"><span>${c.minimum?'Kalkulierter Mindestumfang':'Einmalige Preisorientierung'}</span><b>${euro(c.total)}</b></div></div>${c.quotes.length?`<div class="config-warning"><b>Zusätzlich individuell zu kalkulieren</b><p>${c.quotes.map(esc).join(', ')}. Diese Leistungen sind noch nicht im angezeigten Betrag enthalten.</p></div>`:''}${c.portalReview?'<div class="config-warning">Dashboard und Projektstatus überschneiden sich möglicherweise. Die Schätzung addiert zunächst beide Leistungen; den gemeinsamen Umfang und möglichen Minderaufwand prüfen wir im Angebot.</div>':''}<label class="config-field">Optionale monatliche Betreuung<select id="config-care">${M.care.map(x=>`<option value="${x.id}" ${state.care===x.id?'selected':''}>${x.name}${x.price?' · ab '+euro(x.price)+'/Monat':''}</option>`).join('')}</select></label><p class="config-hint">Für einfache statische Websites: Erreichbarkeitsprüfung, monatlicher Formularcheck und Sicherung. Bei 59 € zusätzlich 30 Minuten, bei 119 € 90 Minuten Inhaltsänderungen. Zeit wird nicht angesammelt. Hosting, Lizenzen und Portalwartung separat.</p><details class="config-scope"><summary>Was ist vorausgesetzt?</summary><p>Gelieferte Texte und Bilder, sofern nicht zugebucht. Standardseiten mit bis zu fünf Inhaltsabschnitten im vereinbarten Stil. Premium enthält eine Scroll-Sequenz mit geeignetem geliefertem Material und dezente Animationen. Keine eigene Video- oder 3D-Produktion. Preise sind unverbindliche Orientierung; finale Leistungen, Laufkosten und steuerliche Ausweisung stehen im persönlichen Angebot.</p></details><button type="button" id="config-download" class="config-secondary">Zusammenstellung herunterladen ↓</button><button type="button" id="config-reset" class="config-reset">Neu beginnen</button><p id="config-summary-status" role="status"></p>`;}
function renderPanel(){ $('#config-panel').innerHTML=step===0?inputPanel():step===1?extrasPanel():summaryPanel();root.querySelectorAll('[data-step]').forEach(b=>{if(Number(b.dataset.step)===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('#config-back').disabled=step===0;$('#config-next').hidden=step===2;$('#config-next').textContent=step===0?'Weiter zu den Extras ↗':'Zur Übersicht ↗';}
function prices(){const c=M.calculate(state);showPriceDelta(c.total-(lastTotal??c.total));lastTotal=c.total;const attached=document.querySelector('[name="website_configuration"]');if(attached){attached.value=summaryText();const p=document.querySelector('#configuration-attached p');if(p)p.textContent='Aktuelle Website-Zusammenstellung beigefügt: '+M.packages[state.package].name+' · '+(c.minimum?'ab ':'')+euro(c.total)+(c.quotes.length?' zuzüglich individuell zu kalkulierender Wünsche.':'.')+' Ergänze deine Kontaktdaten und sende deine Anfrage.';}$('#config-total').textContent=(c.minimum?'ab ':'')+euro(c.total);$('#config-price-label').textContent=c.quotes.length?'Teilbetrag · weitere Wünsche offen':'Einmalige Preisorientierung';$('#config-monthly').textContent=c.monthly?'zzgl. Betreuung ab '+euro(c.monthly)+' / Monat':'Keine monatliche Betreuung gewählt';$('#config-qualifier').textContent=c.quotes.length?'Zusätzlich nach Angebot: '+c.quotes.join(', ')+'.': 'Unverbindlich. Hosting und externe Kosten separat.';let hint=$('#config-saving');if(!hint){hint=document.createElement('div');hint.id='config-saving';hint.className='config-saving';$('.config-controls').append(hint);}hint.hidden=!c.saving;hint.innerHTML=c.saving?`<span>Business bietet dir hier mehr Umfang für <b>${euro(c.saving)} weniger.</b></span><button type="button" data-package="business">Zu Business wechseln ↗</button>`:'';}
function block(id,title,body){return `<section class="pv-block" data-pv-block="${id}"><span class="pv-eyebrow">${esc(state.name||'Dein Unternehmen')}</span><h3>${esc(sectionTitle(id,title))}</h3>${body}</section>`;}
function preview(){const v=$('#preview-site'),oldScroll=v.scrollTop;const ind=industries[state.industry];const extras=state.extras;const nav=['Start','Leistungen','Über uns','Projekte','Kontakt'];while(nav.length<state.pages)nav.push('Seite '+(nav.length+1));const pages=state.pages===1?['Start']:nav.slice(0,state.pages);if(extras.career)pages.push('Karriere');for(let n=0;n<(extras.case||0);n++)pages.push('Projekt '+(n+1));if(!pages.includes(page))page='Start';const isHome=page==='Start';let body='';
if(isHome){body=`<section data-pv-block="hero" class="pv-hero ${state.package==='premium'?'pv-cinematic':''}"><p class="pv-eyebrow">${esc(ind.label)} · BEISPIELVORSCHAU</p><h2>${esc(sectionTitle('hero',ind.headline))}</h2><p>${ind.sub}</p><button type="button" data-pv-contact>${ind.cta} ↗</button><img class="pv-industry-image" src="${ind.image}" alt="${ind.imageAlt}"><p class="pv-industry-note">Branchenbeispiel · dein eigener Auftritt wird individuell gestaltet.</p><div class="pv-hero-bottom"><span>${state.package==='premium'?'01 / SCROLL EXPERIENCE':'PERSÖNLICH. VON ANFANG AN.'}</span><span>↓</span></div></section>`;
if(extras.video)body+=block('video','Ein Eindruck in Bewegung.',`<video controls muted loop playsinline preload="none" poster="assets/img/avanti-reel-poster.jpg" aria-label="Beispielvideo für den Video-Hero"><source src="assets/video/avanti-reel-web.mp4" type="video/mp4"></video><small>Beispielmedium · wird durch dein eigenes Video ersetzt</small>`);
body+=block('services','Was wir für dich tun.',`<div class="pv-services">${ind.services.map(([title,copy],i)=>`<article><b>0${i+1} / ${title}</b><p>${copy}</p></article>`).join('')}</div>`);
body+=block('about',ind.about,`<div class="pv-about-layout"><div class="pv-monogram" aria-hidden="true">${esc((state.name||'Dein Unternehmen').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase())}</div><div><p>${ind.aboutCopy}</p><div class="pv-values"><span>Persönlicher Kontakt</span><span>Klare Absprachen</span></div></div></div>`);
body+=block('process','So geht es weiter.',`<ol class="pv-process">${ind.process.map(([title,copy],i)=>`<li><span>0${i+1}</span><div><b>${title}</b><p>${copy}</p></div></li>`).join('')}</ol>`);
if(state.package==='premium'||extras.cinema)body+=`<section class="pv-scroll" data-pv-block="cinema"><span>BEISPIEL EINER SCROLL-SEQUENZ</span><strong>Jedes Detail.<br>Ein gutes Gefühl.</strong><p>Scrolle innerhalb der Vorschau.</p><div class="pv-scroll-detail">Präzision wird sichtbar.<br><small>${(state.package==='premium'?1:0)+(extras.cinema||0)} Sequenz${(state.package==='premium'?1:0)+(extras.cinema||0)>1?'en':''} im gewählten Umfang</small></div></section>`;
}else body=block('page',esc(page),`<p>${page==='Kontakt'?'Lass uns über dein Vorhaben sprechen.':page==='Über uns'?'Menschen, Erfahrung und eine gemeinsame Haltung.':'Hier bekommen deine Inhalte den Raum, den sie verdienen.'}</p>`);
if(extras.gallery||extras.filter||page==='Projekte'||page.startsWith('Projekt ')){const projects=[{type:'Projekt',name:'Butz-Bauwelt',sector:'Bau & Wohnen',image:'assets/references/butz-bauwelt-hires.webp'},{type:'Detail',name:'Avanti Haarstudio',sector:'Beauty & Lifestyle',image:'assets/references/ref-03-avanti-haarstudio-v8.webp'},{type:'Projekt',name:'Kopp-Dach',sector:'Dachhandwerk',image:'assets/references/kopp-dach.png'}];body+=block('gallery','Jedes Projekt erzählt eine Geschichte.',`${extras.filter?'<div class="pv-filters"><button type="button" data-pv-filter="Alle" aria-pressed="'+(filter==='Alle')+'">Alle</button><button type="button" data-pv-filter="Projekt" aria-pressed="'+(filter==='Projekt')+'">Projekt</button><button type="button" data-pv-filter="Detail" aria-pressed="'+(filter==='Detail')+'">Detail</button></div>':''}<div class="pv-gallery">${projects.filter(p=>filter==='Alle'||!extras.filter||filter===p.type).map((p,i)=>`<button type="button" data-pv-detail="${p.name}" data-gallery-image="${p.image}"><div class="pv-gallery-picture"><img src="${p.image}" alt="Website-Projekt ${p.name}" loading="lazy"><i aria-hidden="true">↗</i></div><span><b>${p.name}</b><small>${p.sector}</small></span></button>`).join('')}</div><small>Reale Kaiser-Projekte als Beispielmaterial. Hier erscheinen später deine eigenen Arbeiten.</small>`);}
if(extras.compare)body+=block('compare','Vorher. Nachher.',`<div class="pv-compare" style="--split:50%"><img src="${ind.image}" alt="Vergleichsdemo"><img class="pv-compare-overlay" src="${ind.image}" alt=""><span>Vorher</span><span>Nachher</span></div><label class="pv-range">Vergleich verschieben<input type="range" min="0" max="100" value="50" data-pv-compare></label><small>Funktionsdemo mit gleichem Motiv und Farbeffekt.</small>`);
if(extras.team||page==='Über uns')body+=block('team','Die Menschen dahinter.','<div class="pv-team"><span aria-hidden="true">AM</span><div><b>Alex Muster</b><p>Beratung & Projektleitung · Beispielprofil</p></div></div>');
if(extras.reviews||extras.reviewfeed)body+=block('reviews','Was Kunden sagen.','<blockquote>„Hier steht später eine echte, freigegebene Kundenstimme.“</blockquote><small>Platzhalter · keine echte Bewertung</small>');
if(extras.downloads)body+=block('downloads','Alles Wichtige zum Mitnehmen.','<button type="button" data-pv-demo="Ein eigener Downloadbereich stellt deine Dokumente bereit.">Informationsbroschüre · Demo ↓</button>');
if(extras.locations)body+=block('locations','In deiner Nähe.','<div class="pv-services"><article><b>Standort Nord</b><p>Adresse und Kontakt</p></article><article><b>Standort Süd</b><p>Adresse und Kontakt</p></article></div>');
if(extras.catalog||extras.search){body+=block('search',extras.catalog?'Finde die passende Leistung.':'Was suchst du?',`<label>Suchbegriff<input data-pv-search placeholder="Zum Beispiel Beratung" value="${esc(search)}"></label><div class="pv-results">${ind.services.map(x=>x[0]).filter(t=>t.toLowerCase().includes(search.toLowerCase())).map(t=>'<p>'+t+' ↗</p>').join('')||'<p>Kein Treffer. Versuche einen anderen Begriff.</p>'}</div>`);}
if(extras.pricelist)body+=block('pricelist','Leistungen im Überblick.','<details><summary>Beratung ↗</summary><p>Hier erscheinen deine Leistungen und Preise.</p></details><details><summary>Umsetzung ↗</summary><p>Beispiel einer aufklappbaren Kategorie.</p></details>');
if(extras.faq)body+=block('faq','Gut zu wissen.','<label>Antwort suchen<input data-faq-search placeholder="Frage eingeben"></label><div data-faq-items><details><summary>Wie läuft die Zusammenarbeit ab?</summary><p>Wir lernen dein Vorhaben kennen und besprechen die nächsten Schritte.</p></details><details><summary>Wie erreiche ich euch?</summary><p>Nutze das Kontaktformular.</p></details></div>');
if(extras.blog||extras.events)body+=block('news',extras.events?'Was als Nächstes kommt.':'Einblicke & Neuigkeiten.','<article class="pv-news"><span>BEISPIELEINTRAG</span><h4>Ein Blick hinter die Kulissen.</h4><button type="button" data-pv-detail="Einblicke & Neuigkeiten">Beitrag öffnen ↗</button></article>');
if(extras.career||page==='Karriere')body+=block('career','Dein nächstes Kapitel.','<p>Werde Teil unseres Teams.</p><details><summary>Offene Stelle · Beispiel</summary><p>Aufgaben, Profil und Vorteile bekommen hier ihren Platz.</p></details>');
if(extras.application)body+=block('application','Lernen wir uns kennen.','<label>Lebenslauf<input type="file" accept="application/pdf" data-pv-upload></label><small>Funktionsdemo: Dateien werden nicht hochgeladen.</small>');
if(extras.booking)body+=block('booking','Zeit für ein Gespräch.',`<div class="pv-booking">${['Mo · 10:00','Di · 14:30','Do · 11:00'].map(t=>`<button type="button" data-pv-demo="${t} ausgewählt. Dies ist eine Demo; es wird kein Termin gebucht.">${t}</button>`).join('')}</div><small>Beispieltermine · keine echte Buchung</small>`);
if(extras.calculator)body+=block('calculator','Dein Bedarf. Auf einen Blick.','<label>Beispielmenge<input type="range" min="1" max="10" value="3" data-pv-calc></label><output data-pv-calc-output>Beispielwert: 300 €</output><small>Demoformel: Menge × 100 €. Deine Kalkulation wird individuell definiert.</small>');
if(extras.newsletter)body+=block('newsletter','Bleib auf dem Laufenden.','<label>E-Mail<input type="email" placeholder="name@beispiel.de"></label><button type="button" data-pv-demo="Newsletter-Demo. Es werden keine Daten versendet.">Anmelden ↗</button>');
if(extras.member||extras.portal)body+=block('member','Dein persönlicher Bereich.',`<p>Login-Demo · ohne echte Anmeldung</p><button type="button" data-pv-login>Demo-Kundenbereich öffnen ↗</button><div data-pv-dashboard hidden><h4>Willkommen, Alex.</h4><p>Deine geschützten Inhalte an einem Ort.</p>${extras.documents?'<p>↓ Persönliche Dokumente · Beispieldatei</p>':''}${extras.uploads?'<label>Dokument auswählen<input type="file" data-pv-upload></label>':''}${extras.dashboard?'<div class="pv-services"><article>2<br>Projekte</article><article>3<br>Dokumente</article><article>1<br>Nachricht</article></div>':''}${extras.status?'<label>Dein Projekt · Umsetzung<progress max="100" value="65">65 %</progress></label>':''}${extras.role?'<p>Rollenbasierte Freigaben vorgesehen</p>':''}${extras.notifications?'<p>Benachrichtigungen: aktiv · Demo</p>':''}<small>Alle Daten sind erfunden. Dateien werden nicht hochgeladen.</small></div>`);
if(extras.model)body+=block('model','Dein Produkt. Aus jeder Perspektive.','<p>Hier wird dein geliefertes 3D-Modell interaktiv eingebunden.</p><small>Ein eigenes Modell ist für diese Vorschau noch nicht hinterlegt.</small>');
for(let i=0;i<(extras.sections||0);i++)body+=block('section'+i,'Mehr Raum für deine Inhalte.','<p>Zusätzlicher Abschnitt '+(i+1)+' · zum Beispiel Leistungen, Geschichte oder FAQ.</p>');
if(extras.shop||extras.subscription||extras.integration)body+=block('individual','Deine besondere Idee.',`<p>${[extras.shop?'Onlineshop':null,extras.subscription?'Bezahlte Mitgliedschaft':null,extras.integration?'Individuelle Schnittstelle':null].filter(Boolean).join(' · ')}</p><small>Umsetzung und Vorschau nach gemeinsamer Konzeption.</small>`);
body+=block('contact',extras.form?'Erzähl uns von deinem Vorhaben.':ind.contact,`${extras.form?'<div class="pv-form-steps">01 Vorhaben → 02 Details → 03 Kontakt</div>':''}<div class="pv-contact-intro"><span>DEIN DIREKTER DRAHT</span><p>${ind.contactCopy}</p></div><label>${extras.form?'Worum geht es?':'Dein Name'}<input placeholder="${extras.form?'Dein Projekt':'Alex Muster'}"></label>${!extras.form?'<label>Deine E-Mail<input type="email" placeholder="name@beispiel.de"></label><label>Deine Nachricht<textarea rows="3" placeholder="Was möchtest du mit uns besprechen?"></textarea></label>':''}<button type="button" ${extras.form?'data-pv-form':'data-pv-demo="Formular-Demo. Es wird keine Nachricht versendet."'}>${extras.form?'Nächster Schritt':'Nachricht senden'} ↗</button><small>Formularvorschau · kein Versand</small>`);
v.dataset.palette=state.palette;v.dataset.style=state.style;v.dataset.dark=String(state.dark);v.style.setProperty('--pv-accent',state.color);v.style.setProperty('--pv-accent2',state.accent2||state.color);v.style.setProperty('--pv-bg',state.background||(state.dark?'#17181d':'#f7f8f9'));const hex=state.color.slice(1),brightness=parseInt(hex.slice(0,2),16)*.299+parseInt(hex.slice(2,4),16)*.587+parseInt(hex.slice(4,6),16)*.114;v.style.setProperty('--pv-on-accent',brightness>145?'#151713':'#fff');v.innerHTML=`<header class="pv-header"><b>${esc(state.name||'Dein Unternehmen')}</b><nav aria-label="Beispielnavigation">${pages.map(n=>`<button type="button" data-page="${esc(n)}" aria-pressed="${n===page}">${esc(n)}</button>`).join('')}${extras.language?'<button type="button" data-pv-demo="Sprachwechsel vorgesehen. Die Übersetzungen werden später eingebunden.">DE / EN</button>':''}</nav></header>${body}<footer class="pv-footer"><b>${esc(state.name||'Dein Unternehmen')}</b><p>Persönlich. Verlässlich. Für dein Vorhaben.</p><div><span>Impressum</span><span>Datenschutz</span><span>Kontakt</span></div><small>Beispielgestaltung · Inhalte werden individuell abgestimmt.</small></footer><div class="pv-notice" id="pv-notice" role="status" hidden></div>`;applySectionOrder(v);v.scrollTop=oldScroll;decoratePreview();}

const sectionNames={about:'Unternehmen vorstellen',process:'Zusammenarbeit / Ablauf',hero:'Einstieg / Hero',services:'Leistungen',cinema:'Scroll-Erlebnis',video:'Video',gallery:'Projekte & Galerie',compare:'Vorher / Nachher',team:'Team',reviews:'Kundenstimmen',downloads:'Downloads',locations:'Standorte',search:'Suche & Katalog',pricelist:'Preisliste',faq:'Fragen & Antworten',news:'News / Veranstaltungen',career:'Karriere',application:'Bewerbung',booking:'Terminbuchung',calculator:'Preisrechner',newsletter:'Newsletter',member:'Kundenbereich',model:'3D-Präsentation',individual:'Individuelle Funktionen',contact:'Kontaktformular',page:'Seiteninhalt'};
function applySectionOrder(v){const blocks=[...v.querySelectorAll('[data-pv-block]')];if(!blocks.length)return;const footer=v.querySelector('.pv-footer');const current=blocks.map(b=>b.dataset.pvBlock);const saved=(state.sectionOrder||[]).filter(id=>current.includes(id));const order=[...saved,...current.filter(id=>!saved.includes(id))];state.sectionOrder=order;order.forEach(id=>{const el=v.querySelector('[data-pv-block="'+id+'"]');if(el&&footer)v.insertBefore(el,footer);});}
function decoratePreview(){
 const v=$('#preview-site');v.classList.toggle('show-structure',structure);
 const blocks=[...v.querySelectorAll('[data-pv-block]')];
 if(!blocks.some(b=>b.dataset.pvBlock===activeBlock))activeBlock=blocks[0]?.dataset.pvBlock;
 blocks.forEach((b,i)=>{const id=b.dataset.pvBlock,title=sectionNames[id]||(id.startsWith('section')?'Zusätzlicher Abschnitt '+(Number(id.slice(7))+1):id);b.dataset.sectionName=title;const label=document.createElement('div');label.className='pv-section-label';const fixedUp=i===0,fixedDown=i===blocks.length-1;label.innerHTML='<span>'+String(i+1).padStart(2,'0')+' / '+esc(title)+'</span><div class="pv-section-actions"><small>'+((['hero','services','about','process','contact','page'].includes(id)||(id==='cinema'&&state.package==='premium'))?'Im Paket':'Ergänzung')+'</small><button type="button" data-section-edit="'+id+'">Bearbeiten</button><button type="button" data-section-up="'+id+'" aria-label="Abschnitt nach oben" '+(fixedUp?'disabled':'')+'>↑</button><button type="button" data-section-down="'+id+'" aria-label="Abschnitt nach unten" '+(fixedDown?'disabled':'')+'>↓</button></div>';b.prepend(label);b.classList.toggle('is-active-section',id===activeBlock);});
 $('#section-map').innerHTML=blocks.map((b,i)=>'<button type="button" data-jump-section="'+b.dataset.pvBlock+'" aria-pressed="'+(b.dataset.pvBlock===activeBlock)+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(b.dataset.sectionName)+'</button>').join('');
 $('#section-count').textContent=blocks.length+' Abschnitte · '+page;
 $('#preview-structure').setAttribute('aria-pressed',String(structure));
}
function moveSection(id,dir){const v=$('#preview-site');const ids=[...v.querySelectorAll('[data-pv-block]')].map(x=>x.dataset.pvBlock);const i=ids.indexOf(id),j=i+dir;if(i<0||j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];state.sectionOrder=ids;activeBlock=id;preview();focusSection(id);syncStudioUI();}
function openSectionEditor(id){const v=$('#preview-site'),target=v.querySelector('[data-pv-block="'+id+'"]');if(!target)return;const heading=target.querySelector('h2,h3');let editor=$('#section-editor');if(!editor){editor=document.createElement('div');editor.id='section-editor';editor.className='section-editor';$('.config-visual').append(editor);}editor.innerHTML=`<div><span>ABSCHNITT BEARBEITEN</span><button type="button" data-section-close aria-label="Schließen">×</button></div><b>${esc(target.dataset.sectionName||id)}</b><label>Überschrift<input data-section-title-input="${id}" maxlength="80" value="${esc(heading?.textContent||'')}"></label><div><button type="button" data-section-reset="${id}">Original wiederherstellen</button><button type="button" data-section-close>Fertig</button></div>`;editor.hidden=false;editor.querySelector('input')?.focus();}
function focusSection(id,added=false){
 const v=$('#preview-site'),target=v.querySelector('[data-pv-block="'+id+'"]');if(!target)return;
 activeBlock=id;v.querySelectorAll('[data-pv-block]').forEach(b=>b.classList.toggle('is-active-section',b===target));
 root.querySelectorAll('[data-jump-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.jumpSection===id)));
 const top=target.getBoundingClientRect().top-v.getBoundingClientRect().top+v.scrollTop;
 v.scrollTop=Math.max(0,top-12);
 if(added){target.classList.add('section-added');setTimeout(()=>target.classList.remove('section-added'),1800);}
 $('#preview-update').textContent=(added?'Hinzugefügt: ':'Im Blick: ')+target.dataset.sectionName;
}

function ensureStudioShell(){const bar=$('.config-bar');if(bar&&!$('#config-hud')){const hud=document.createElement('div');hud.id='config-hud';hud.className='config-live-hud';bar.insertBefore(hud,$('#config-expand'));}const grid=$('.config-grid');if(grid&&!$('#config-project-rail')){const rail=document.createElement('aside');rail.id='config-project-rail';rail.className='config-project-rail';rail.setAttribute('aria-label','Dein Projekt im Überblick');grid.append(rail);}}
function syncStudioUI(){ensureStudioShell();const c=M.calculate(state),goal=goalInfo(),blocks=[...$('#preview-site').querySelectorAll('[data-pv-block]')],extraCount=selectedExtraCount();const hud=$('#config-hud');if(hud)hud.innerHTML=`<span>${blocks.length} MODULE</span><span>${state.style==='editorial'?'ELEGANT':state.style==='bold'?'MARKANT':'KLAR'}</span><strong>${c.minimum?'AB ':''}${euro(c.total)}</strong>`;const rail=$('#config-project-rail');if(!rail)return;if(!desktopView()){const readyCount=Object.values(state.content||{}).filter(v=>v==='ready').length;rail.innerHTML=`<div class="mobile-project-summary"><span>DEIN PROJEKT</span><strong>${M.packages[state.package].name} · ${c.totalPages} Seite${c.totalPages===1?'':'n'} · ${extraCount} Extra${extraCount===1?'':'s'}</strong><b>${c.minimum?'ab ':''}${euro(c.total)}</b><small>${goal.label} · Content ${readyCount}/3 vorbereitet</small></div>`;return;}const readiness=Object.entries(contentLabels).map(([id,label])=>`<li class="${contentState(id)==='ready'?'is-ready':''}"><span>${contentState(id)==='ready'?'✓':'○'}</span>${label}<small>${contentState(id)==='ready'?'vorhanden':'offen'}</small></li>`).join('');const sitemap=pageNames().map(pg=>`<div class="sitemap-page ${pg===page?'is-current':''}"><button type="button" data-page="${esc(pg)}"><span>${pg===page?'●':'○'}</span>${esc(pg)}</button>${pg===page?`<div class="sitemap-sections">${blocks.map((b,i)=>`<button type="button" data-jump-section="${b.dataset.pvBlock}"><span>${String(i+1).padStart(2,'0')}</span>${esc(b.dataset.sectionName||b.dataset.pvBlock)}</button>`).join('')}</div>`:''}</div>`).join('');rail.innerHTML=`<div class="project-rail-head"><span>DEIN PROJEKT</span><strong>${state.name&&state.name!=='Dein Unternehmen'?esc(state.name):'Website Studio'}</strong><p>${goal.label} · ${industries[state.industry].label}</p></div><div class="project-metrics"><article><span>Paket</span><b>${M.packages[state.package].name}</b></article><article><span>Seiten</span><b>${c.totalPages}</b></article><article><span>Extras</span><b>${extraCount}</b></article><article><span>Abschnitte</span><b>${blocks.length}</b></article></div><div class="project-price"><span>${c.minimum?'Kalkulierter Mindestumfang':'Aktuelle Orientierung'}</span><strong>${c.minimum?'ab ':''}${euro(c.total)}</strong><small>${c.monthly?'zzgl. '+euro(c.monthly)+'/Monat Betreuung':'ohne laufende Betreuung'}</small></div><div class="project-rail-section"><div class="rail-title"><span>SEITENSTRUKTUR</span><small>Klickbar</small></div><div class="sitemap-tree">${sitemap}</div></div><div class="project-rail-section"><div class="rail-title"><span>CONTENT-CHECK</span><small>Briefing</small></div><ul class="readiness-list">${readiness}</ul>${contentState('text')==='open'&&!state.extras.copy?'<button type="button" class="rail-action" data-rec-add="copy">Texterstellung hinzufügen +</button>':''}</div><div class="project-rail-section"><div class="rail-title"><span>EMPFOHLEN</span><small>${esc(goal.short)}</small></div><div class="rail-recs">${recommendationItems().map(x=>{const included=x.id==='motion'&&state.package==='premium',chosen=!!state.extras[x.id]||included;return `<button type="button" data-rec-add="${x.id}" aria-pressed="${chosen}" ${included?'disabled':''}><span>${chosen?'✓':'+'}</span>${esc(x.name)}${chosen&&!included?'<small>abwählen</small>':''}</button>`;}).join('')}</div></div>`;}
function showPriceDelta(delta){if(lastTotal===null||!delta)return;const host=$('.config-totalbar');let toast=$('#config-price-delta');if(!toast){toast=document.createElement('div');toast.id='config-price-delta';toast.className='config-price-delta';host.append(toast);}toast.textContent=(delta>0?'+':'−')+euro(Math.abs(delta));toast.classList.remove('is-visible');requestAnimationFrame(()=>toast.classList.add('is-visible'));clearTimeout(showPriceDelta.timer);showPriceDelta.timer=setTimeout(()=>toast.classList.remove('is-visible'),1700);}
function update(note,full=true){const active=document.activeElement;const focusKey=active?.id?'#'+active.id:active?.dataset.extra?'[data-extra="'+active.dataset.extra+'"]':null;state=M.normalize(state);state.content={...M.initial().content,...(state.content||{})};state.sectionTitles=state.sectionTitles||{};state.sectionOrder=state.sectionOrder||[];packageCards();if(full)renderPanel();prices();preview();applyDeviceUI();syncStudioUI();if(note)$('#preview-update').textContent=note;if(focusKey&&root.querySelector(focusKey))root.querySelector(focusKey).focus({preventScroll:true});}
function go(n){step=n;renderPanel();const title=$('#config-panel h3');title.tabIndex=-1;title.focus({preventScroll:true});}
function summaryText(){const c=M.calculate(state);return ['KAISER WEBDESIGN · DEINE ZUSAMMENSTELLUNG','Unverbindliche Preisorientierung','Paketumfang: '+packageInfo[state.package].features.join('; '),`Unternehmen: ${state.name}`,`Branche: ${industries[state.industry].label}`,`Ziel: ${goalInfo().label}`,`Gestaltung: ${state.style} · ${state.palette||'custom'} · Primary ${state.color} · Accent ${state.accent2||state.color} · Background ${state.background||''} · ${state.dark?'dunkel':'hell'}`,`Content: Texte ${contentState('text')==='ready'?'vorhanden':'offen'} · Bilder ${contentState('images')==='ready'?'vorhanden':'offen'} · Logo ${contentState('logo')==='ready'?'vorhanden':'offen'}`,`Inhaltsseiten: ${c.totalPages} (davon ${state.pages} regulär)`,...c.lines.map(l=>`${l.name}: ${l.min?'ab ':''}${euro(l.amount)}`),`Einmalig: ${c.minimum?'ab ':''}${euro(c.total)}`,`Betreuung: ${c.monthly?'ab '+euro(c.monthly)+'/Monat':'nicht gewählt'}`,c.quotes.length?'Zusätzlich nach Angebot, NICHT im Betrag enthalten: '+c.quotes.join(', '):'',c.portalReview?'Dashboard / Projektstatus: Überschneidungen im Angebot prüfen.':'','Hosting, Domain, Lizenzen und externe Dienste separat. Portalwartung individuell.','Gelieferte Texte/Bilder, sofern nicht zugebucht. Finale Preise, Umfang und steuerliche Ausweisung im persönlichen Angebot.'].filter(Boolean).join('\n');}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.goal){state.goal=d.goal;update('Ziel angepasst – Empfehlungen wurden aktualisiert.');}
if(d.palette){const p=palettes[d.palette];state.palette=d.palette;state.color=p.primary;state.accent2=p.accent;state.background=p.bg;state.dark=p.dark;update('Farbwelt '+p.label+' angewendet.');}
if(d.content&&d.contentStatus){state.content={...(state.content||{}),[d.content]:d.contentStatus};update(contentLabels[d.content]+'-Status aktualisiert.');}
if(d.recAdd){const x=M.extras.find(e=>e.id===d.recAdd);if(x){const included=x.id==='motion'&&state.package==='premium';if(!included){const chosen=!!state.extras[x.id],value=chosen?0:(x.type==='qty'?(x.id==='copy'?Math.max(1,state.pages):1):1);state=M.setExtra(state,x.id,value);filter='Alle';update(chosen?x.name+' wurde abgewählt.':x.name+' wurde eingeplant.');}}}
if(d.sectionEdit){openSectionEditor(d.sectionEdit);}
if(d.sectionUp){moveSection(d.sectionUp,-1);}
if(d.sectionDown){moveSection(d.sectionDown,1);}
if(d.sectionClose!==undefined){const ed=$('#section-editor');if(ed)ed.hidden=true;}
if(d.sectionReset){delete state.sectionTitles[d.sectionReset];preview();syncStudioUI();openSectionEditor(d.sectionReset);}
if(b.id==='preview-structure'){structure=!structure;$('#preview-site').classList.toggle('show-structure',structure);b.setAttribute('aria-pressed',String(structure));}if(d.jumpSection){focusSection(d.jumpSection);}if(b.id==='preview-show'){const target=$('.config-visual');target.scrollIntoView({behavior:'smooth',block:'start'});}if(d.package){const hadExtraPages=state.pages>M.packages[state.package].pages;state.package=d.package;state.pages=hadExtraPages?Math.max(state.pages,M.packages[d.package].pages):M.packages[d.package].pages;page='Start';update(M.packages[d.package].name+' ausgewählt.');}
if(d.step!==undefined)go(Number(d.step));if(b.id==='config-next')go(Math.min(2,step+1));if(b.id==='config-back')go(Math.max(0,step-1));
if(d.style){state.style=d.style;update('Gestaltungsrichtung angepasst.');}if(d.color){state.color=d.color;update('Akzentfarbe angepasst.');}if(d.pages){state.pages+=Number(d.pages);update('Navigation und Seitenumfang aktualisiert.');}if(d.category){category=d.category;renderPanel();root.querySelector('[data-category="'+category+'"]').focus({preventScroll:true});}
if(d.quantity){state=M.setExtra(state,d.quantity,(state.extras[d.quantity]||0)+Number(d.delta));update('Umfang aktualisiert.');}
if(d.device&&desktopView()){device=d.device;applyDeviceUI();}
if(d.page){page=d.page;preview();$('#preview-site').scrollTop=0;syncStudioUI();}if(d.pvFilter){filter=d.pvFilter;preview();}
if(d.pvContact!==undefined){$('#preview-site [data-pv-block="contact"]').scrollIntoView({block:'nearest',behavior:'smooth'});}
if(d.pvForm!==undefined){const zone=b.closest('.pv-block');zone.querySelector('label').innerHTML='Deine E-Mail<input type="email" placeholder="name@beispiel.de">';zone.querySelector('.pv-form-steps').textContent='02 Kontakt → 03 Zusammenfassung';b.textContent='Demo abschließen ↗';delete b.dataset.pvForm;b.dataset.pvDemo='Anfrage-Assistent abgeschlossen. In dieser Demo werden keine Daten versendet.';}if(d.pvDemo)notice(d.pvDemo);if(d.pvLogin!==undefined){const el=$('[data-pv-dashboard]');el.hidden=!el.hidden;b.textContent=el.hidden?'Demo-Kundenbereich öffnen ↗':'Demo-Kundenbereich schließen';}
if(d.pvDetail){const card=b.closest('.pv-block');let detail=card.querySelector('.pv-detail');if(!detail){detail=document.createElement('div');detail.className='pv-detail';card.append(detail);}detail.replaceChildren();if(d.galleryImage){const img=document.createElement('img');img.src=d.galleryImage;img.alt=d.pvDetail+' – Projektansicht';detail.append(img);}const caption=document.createElement('p');caption.textContent=d.pvDetail+' — Beispiel einer ausführlichen Projektansicht. Deine eigenen Bilder und Projekttexte kommen später hinzu.';detail.append(caption);const close=document.createElement('button');close.type='button';close.textContent='Detailansicht schließen ×';close.onclick=()=>detail.remove();detail.append(close);}
if(b.id==='config-expand'&&desktopView()){expanded=!expanded;applyViewMode();}
if(b.id==='config-download'){const blob=new Blob([summaryText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Kaiser-Website-Konfiguration.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#config-summary-status').textContent='Deine Zusammenstellung wurde zum Download bereitgestellt.';}
if(b.id==='config-reset'){if(b.dataset.confirm==='yes'){state=M.initial();step=0;page='Start';update('Neue Konfiguration gestartet.');}else{b.dataset.confirm='yes';b.textContent='Auswahl wirklich zurücksetzen?';}}
if(b.id==='config-request'){const form=$('[data-contact-form]');let input=form.querySelector('[name="website_configuration"]');if(!input){input=document.createElement('input');input.type='hidden';input.name='website_configuration';form.append(input);}input.value=summaryText();let status=$('#configuration-attached');if(!status){status=document.createElement('div');status.id='configuration-attached';status.className='configuration-attached';form.prepend(status);}status.replaceChildren();const text=document.createElement('p');text.textContent='Deine Website-Zusammenstellung ist beigefügt: '+M.packages[state.package].name+' · '+euro(M.calculate(state).total)+' Preisorientierung. Ergänze deine Kontaktdaten und sende deine Anfrage.';status.append(text);const remove=document.createElement('button');remove.type='button';remove.textContent='Zusammenstellung entfernen';remove.onclick=()=>{input.remove();status.remove();};status.append(remove);if(!form.elements.company.value)form.elements.company.value=state.name==='Dein Unternehmen'?'':state.name;if(!form.elements.message.value)form.elements.message.value='Ich interessiere mich für die beigefügte Website-Konfiguration. Bitte besprecht mit mir die nächsten Schritte.';$('#kontakt').scrollIntoView({behavior:'smooth'});form.elements.name.focus({preventScroll:true});}
});
function notice(text){const n=$('#pv-notice');n.hidden=false;n.textContent=text;clearTimeout(notice.timer);notice.timer=setTimeout(()=>{n.hidden=true;},5000);}
root.addEventListener('change',e=>{const el=e.target;if(el.dataset.extra){state=M.setExtra(state,el.dataset.extra,el.checked?1:0);filter='Alle';update(el.checked?'Ergänzung hinzugefügt.':'Ergänzung entfernt.');const id=el.dataset.extra;const target=$('#preview-site [data-pv-block="'+({filter:'gallery',form:'contact',events:'news',blog:'news',reviewfeed:'reviews',dashboard:'member',role:'member',documents:'member',status:'member',uploads:'member',notifications:'member',portal:'member',case:'gallery',sections:'section0',catalog:'search'}[id]||id)+'"]');if(target&&el.checked){focusSection(target.dataset.pvBlock,true);}}
if(el.id==='config-industry'){state.industry=el.value;page='Start';activeBlock='hero';filter='Alle';search='';update(null,false);focusSection('hero',true);$('#preview-update').textContent=industries[state.industry].label+': Bildwelt, Leistungen und Kontaktansprache aktualisiert. Deine Extras bleiben erhalten.';}if(el.id==='config-dark'){state.dark=el.checked;state.palette='custom';update('Darstellung angepasst.',false);}if(el.id==='config-care'){state.care=el.value;prices();syncStudioUI();}if(el.matches('[data-pv-upload]'))notice('Datei nur lokal ausgewählt. Diese Demo lädt nichts hoch.');});
root.addEventListener('input',e=>{const el=e.target;if(el.id==='config-name'){state.name=el.value;preview();prices();syncStudioUI();}if(el.id==='config-color'){state.color=el.value;state.palette='custom';preview();prices();syncStudioUI();}if(el.id==='config-accent-color'){state.accent2=el.value;state.palette='custom';preview();syncStudioUI();}if(el.id==='config-bg-color'){state.background=el.value;state.palette='custom';preview();syncStudioUI();}if(el.dataset.sectionTitleInput){state.sectionTitles=state.sectionTitles||{};state.sectionTitles[el.dataset.sectionTitleInput]=el.value;const target=$('#preview-site [data-pv-block="'+el.dataset.sectionTitleInput+'"] h2, #preview-site [data-pv-block="'+el.dataset.sectionTitleInput+'"] h3');if(target)target.textContent=el.value;}if(el.matches('[data-pv-compare]'))el.closest('.pv-block').querySelector('.pv-compare').style.setProperty('--split',el.value+'%');if(el.matches('[data-pv-calc]'))$('[data-pv-calc-output]').textContent='Beispielwert: '+euro(Number(el.value)*100);if(el.matches('[data-pv-search]')){search=el.value;const box=el.closest('.pv-block').querySelector('.pv-results');box.innerHTML=industries[state.industry].services.map(x=>x[0]).filter(t=>t.toLowerCase().includes(search.toLowerCase())).map(t=>'<p>'+t+' ↗</p>').join('')||'<p>Kein Treffer.</p>';}if(el.matches('[data-faq-search]'))root.querySelectorAll('[data-faq-items] details').forEach(d=>d.hidden=!d.textContent.toLowerCase().includes(el.value.toLowerCase()));});
function applyDeviceUI(){if(!desktopView()){device='mobile';structure=false;}const stage=$('.preview-stage');if(stage)stage.classList.toggle('is-mobile',device==='mobile');const site=$('#preview-site');if(site)site.classList.toggle('show-structure',structure);root.querySelectorAll('[data-device]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.device===device)));const structureButton=$('#preview-structure');if(structureButton)structureButton.setAttribute('aria-pressed',String(structure));}
function applyViewMode(){const b=$('#config-expand');if(!b)return;if(!desktopView()){root.classList.remove('is-expanded');b.hidden=true;b.setAttribute('aria-pressed','false');return;}b.hidden=false;root.classList.toggle('is-expanded',expanded);b.setAttribute('aria-pressed',String(expanded));b.textContent=expanded?'Kompakte Ansicht ↙':'Ansicht erweitern ↗';}
let desktopMode=desktopView();
applyViewMode();
applyDeviceUI();
window.addEventListener('resize',()=>{const now=desktopView();if(now!==desktopMode){desktopMode=now;expanded=now;if(!now){device='mobile';structure=false;}else{device='desktop';}applyViewMode();applyDeviceUI();syncStudioUI();}});
update();
})();
